effect.shader:
const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
vec4 src(vec2 uv){ return texture2DCv(inputImg.texture, uv); }
vec4 eTex(vec2 uv){ return texture2DCv(edge.texture, uv); }
void main(){
  vec2 uvs = acScreenNorm.st;
  vec4 baseColor = src(uvs);
  int nSamples = int(quality);
  if( intensity <= 0.0 || nSamples < 2 ) { gl_FragColor = baseColor; return; }

  vec2 texelSize = 1.0 / getTexSize(inputImg.size);
  vec2 center = vec2(0.5 + centerPoint.x/500., 0.5 - centerPoint.y/500.);
  vec2 v = uvs - (vec4(center,0.0,1.0) * acLayerToScreen).xy;
  float speed = length(strength / 2.0 / texelSize);
  speed *= length( acLayerNorm.st - center );
  float vl = length(v);
  vec2 vnorm = (vl > 1.0e-8 ? v/vl : vec2(0.0)) * texelSize * speed;
  vec2 offsetScale = vec2(1., 1.);
  if( acScreenSize.y > acScreenSize.x ) {
    offsetScale.x *= acScreenSize.x / acScreenSize.y;
  } else {
    offsetScale.y *= acScreenSize.y / acScreenSize.x;
  }
  vnorm *= offsetScale;              // hoisted: was re-applied every tap

  // Quality drives nSamples-1 taps spanning p = 0..1. Cap the march at 128
  // taps and stretch the stride so the last tap still lands at p == 1 (ray
  // length unchanged); the 1/nSamples normaliser is rescaled by the same
  // stride so total brightness is unchanged. quality <= 129 is bit-identical.
  int nIter = nSamples - 1;
  int nCap  = nIter < 128 ? nIter : 128;
  float invCap = 1.0 / float(nCap);
  float stride = float(nIter) * invCap;
  // dot() is linear, so the per-tap subtract of thresholdColor folds into
  // one frame-constant offset.
  float thrOff = threshold + dot(thresholdColor.rgb, luminanceWeighting);

  vec4 outColor = vec4(0.0);
  for(int m=1; m<129; m++ ) {
    if(m>nCap) break;
    float p = float(m) * invCap;
    vec2 sp = uvs - vnorm*p;
    // Fetch the edge buffer first: taps that fail the test contributed
    // vec4(0.0) anyway, so their source fetch is pure waste.
    if( dot(eTex(sp).rgb, luminanceWeighting) > thrOff ) {
      vec4 c = (blend >= 1.0) ? fillColor : mix(src(sp), fillColor, blend);
      outColor += c * (1.-p);
    }
  }
  gl_FragColor = baseColor + outColor * (intensity * stride / float(nSamples));
}
